import React from 'react';

// Inline styles for the About Us page
const styles = {
  container: {
    padding: '40px 20px',
    maxWidth: '900px',
    margin: '40px auto', // Added margin-top for spacing from the header
    fontFamily: 'sans-serif',
    color: '#333',
    lineHeight: '1.7',
    backgroundColor: '#f9f9f9',
    borderRadius: '8px',
    boxShadow: '0 4px 8px rgba(0, 0, 0, 0.1)',
  },
  title: {
    fontSize: '2.8rem',
    fontWeight: '700',
    color: '#1a202c',
    marginBottom: '20px',
    textAlign: 'center',
    borderBottom: '3px solid #a7ffeb',
    paddingBottom: '10px',
  },
  content: {
    fontSize: '1.1rem',
    color: '#4a5568',
    padding: '0 15px',
  },
  highlight: {
    fontWeight: '600',
    color: '#2d3748',
  },
  quote: {
    fontStyle: 'italic',
    textAlign: 'center',
    fontSize: '1.2rem',
    margin: '30px 0',
    color: '#1a202c',
    padding: '15px',
    borderLeft: '5px solid #a7ffeb',
    backgroundColor: '#e6fffa',
  },
  link: {
    display: 'inline-block',
    marginTop: '25px',
    padding: '12px 25px',
    backgroundColor: '#1a202c',
    color: '#a7ffeb',
    textDecoration: 'none',
    fontWeight: 'bold',
    borderRadius: '5px',
    transition: 'background-color 0.3s ease, transform 0.2s ease',
  },
};

const AboutUs = () => {
  return (
    <div style={styles.container}>
      <h1 style={styles.title}>About Dietitian Karpagam</h1>
      <div style={styles.content}>
        <p>
          I’m <span style={styles.highlight}>Dietitian Karpagam</span>, a practical and service-oriented nutrition professional with over{' '}
          <span style={styles.highlight}>6 years of experience</span> in clinical and lifestyle nutrition.
        </p>
        <p>
          After completing my <span style={styles.highlight}>M.Sc. in Clinical Nutrition</span> from Sri Ramachandra Institute of Higher Education and Research and working at{' '}
          <span style={styles.highlight}>Apollo Hospitals, Chennai</span>, I’ve helped hundreds of individuals transform their health through science-based, realistic diet plans.
        </p>
        <p>
          At <span style={styles.highlight}>Karps Wellness</span>, I focus on making nutrition simple and sustainable — no fads, no extremes — just mindful eating, consistency, and smart food choices.
        </p>
        <p>
          I also conduct nutrition awareness programs and health talks, spreading one key message:
        </p>
        <blockquote style={styles.quote}>
          "Wellness doesn’t begin in the lab or gym — it begins on your plate."
        </blockquote>
        <p>
          If you’re ready to eat better, feel better, and live better —
        </p>
        <a 
          href="/#contact" // This can link to a section on another page or a different route
          style={styles.link}
          onMouseOver={(e) => e.currentTarget.style.transform = 'scale(1.05)'}
          onMouseOut={(e) => e.currentTarget.style.transform = 'scale(1)'}
        >
          Know More About Me →
        </a>
      </div>
    </div>
  );
};

export default AboutUs;
